    this.elapsed = 0;
    if (typeof seed === 'number') {
      // Seed the RNG for reproducibility
      let x = Math.sin(seed) * 10000;
      this._seededRNG = () => { return (x = Math.sin(x * 9301.0 + 49297.0) % 1); };
    } else {
      this._seededRNG = () => Math.random();
    }

    // Generate maze
    const sizeR = this.size.rows;
    const sizeC = this.size.cols;

    let grid = [];
    for (let r=0;r<sizeR;++r) {
      grid[r]=[];
      for(let c=0;c<sizeC;++c){
        grid[r][c] = {n:true,e:true,s:true,w:true, visited:false}; 
      }
    }

    // Start from (0,0), recursive backtracker
    const stack = [];
    let currentR = Math.floor(this._seededRNG()*sizeR);
    let currentC = Math.floor(this._seededRNG()*sizeC);
    grid[currentR][currentC].visited=true;

    while (true) {
      let neighbors = getUnvisitedNeighbors(currentR,currentC,grid).sort((a,b)=>this._seededRNG()-0.5);
      if (neighbors.length === 0) break;
      const next = neighbors[0];
      stack.push({r:currentR,c:currentC});

      // Remove wall between current and next
      let dr=next.r-currentR, dc=next.c - currentC;
      if (dr ===-1) grid[currentR][currentC].n = false, grid[next.r][next.c].s = false;
      else if (dr===1) grid[currentR][currentC].s=false, grid[next.r][next.c].n=false;
      else if (dc===-1) grid[currentR][currentC].w=false, grid[next.r][next.c].e= false;
      else grid[currentR][currentC].e=false, grid[next.r][next.c].w=false;

      currentR = next.r;
      currentC = next.c;
      grid[currentR][currentC].visited=true;
